#include <iostream>
#include <vector>
#include <queue>
#include <tuple>
#include <cstring>
using namespace std;
​
int t, c; // 最大拐弯次数t，最大破墙数c
int n, m; // 地图大小
vector<vector<char>> grid;
​
// 方向定义：上0，下1，左2，右3
int dx[4] = {-1, 1, 0, 0};
int dy[4] = {0, 0, -1, 1};
​
// 状态压缩 二维 压成 一维
// visited[pos][dir][0] = 该位置该方向下最小拐弯数
// visited[pos][dir][1] = 该位置该方向下最小破墙数
int visited[10000][4][2];
​
struct State {
    int x, y, dir, usedT, usedC;
};
​
bool bfs(int startX, int startY) {
    memset(visited, 0x3f, sizeof(visited)); // 初始化为大数
​
    queue<State> q;
​
    // 起点四个方向均可，拐弯数0，破墙数0
    for (int dir = 0; dir < 4; dir++) {
        visited[startX * m + startY][dir][0] = 0;
        visited[startX * m + startY][dir][1] = 0;
        q.push({startX, startY, dir, 0, 0});
    }
​
    while (!q.empty()) {
        auto [x, y, dir, usedT, usedC] = q.front();
        q.pop();
​
        if (grid[x][y] == 'T') return true;
​
        for (int ndir = 0; ndir < 4; ndir++) {
            int nx = x + dx[ndir];
            int ny = y + dy[ndir];
            // 超过边界
            if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;
​
            int nUsedT = usedT;
            if (ndir != dir) nUsedT++; // 拐弯
            // 超过最大拐弯
            if (nUsedT > t) continue;
​
            int nUsedC = usedC;
            if (grid[nx][ny] == '*') nUsedC++;
            // 超过最大破墙
            if (nUsedC > c) continue;
​
            int pos = nx * m + ny;

            // 剪枝逻辑就是你已这个方向到达这个位置，拐弯和碰撞你肯定要有一个优于之前才能进行下去
            // 剪枝：新状态如果不优于旧状态，则跳过
            if (nUsedT > visited[pos][ndir][0] && nUsedC >= visited[pos][ndir][1]) continue;
            if (nUsedT >= visited[pos][ndir][0] && nUsedC > visited[pos][ndir][1]) continue;

            if (nUsedT == visited[pos][ndir][0] && nUsedC == visited[pos][ndir][1]) continue;
​
            //上述剪枝可以写成这样的哈，为了把情况给各位分清楚所以分步了
            // if (nUsedT >= visited[pos][ndir][0] && nUsedC >= visited[pos][ndir][1]) continue;
​
​
            // 更新状态
            if (nUsedT < visited[pos][ndir][0]) visited[pos][ndir][0] = nUsedT;
            if (nUsedC < visited[pos][ndir][1]) visited[pos][ndir][1] = nUsedC;
​
            q.push({nx, ny, ndir, nUsedT, nUsedC});
        }
    }
    return false;
}
​
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
​
    cin >> t >> c;
    cin >> n >> m;
    grid.resize(n, vector<char>(m));
    int startX = -1, startY = -1;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++) {
            cin >> grid[i][j];
            if (grid[i][j] == 'S') {
                startX = i;
                startY = j;
            }
        }
​
    bool ans = bfs(startX, startY);
    cout << (ans ? "YES" : "NO") << "\n";
    return 0;
}
