package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
type State struct {
    x, y, dir, usedT, usedC int
}
​
var dx = []int{-1, 1, 0, 0}
var dy = []int{0, 0, -1, 1}
​
func bfs(grid [][]byte, t, c, n, m, startX, startY int) bool {
    visited := make([][][][2]int, n)
    for i := range visited {
        visited[i] = make([][][2]int, m)
        for j := range visited[i] {
            visited[i][j] = make([][2]int, 4)
            for d := 0; d < 4; d++ {
                visited[i][j][d] = [2]int{1e9, 1e9} // 初始化为大数
            }
        }
    }
​
    q := []State{}
    for dir := 0; dir < 4; dir++ {
        visited[startX][startY][dir] = [2]int{0, 0}
        q = append(q, State{startX, startY, dir, 0, 0})
    }
​
    for len(q) > 0 {
        s := q[0]
        q = q[1:]
​
        if grid[s.x][s.y] == 'T' {
            return true
        }
​
        for ndir := 0; ndir < 4; ndir++ {
            nx, ny := s.x+dx[ndir], s.y+dy[ndir]
            if nx < 0 || nx >= n || ny < 0 || ny >= m {
                continue
            }
​
            nUsedT := s.usedT
            if ndir != s.dir {
                nUsedT++
            }
            if nUsedT > t {
                continue
            }
​
            nUsedC := s.usedC
            if grid[nx][ny] == '*' {
                nUsedC++
            }
            if nUsedC > c {
                continue
            }
​
            // 剪枝逻辑就是你已这个方向到达这个位置，拐弯和碰撞你肯定要有一个优于之前才能进行下去
            // 剪枝：新状态如果不优于旧状态，则跳过            
            old := visited[nx][ny][ndir]
            if nUsedT > old[0] && nUsedC >= old[1] {
                continue
            }
            if nUsedT >= old[0] && nUsedC > old[1] {
                continue
            }           
            if nUsedT == old[0] && nUsedC == old[1] {
                continue
            }

            // 上述剪枝可以写成这样的哈，为了把情况给各位分清楚所以分步了   
            // if nUsedT >= old[0] && nUsedC >= old[1] {
            //  continue
            // }
​
​
            if nUsedT < old[0] {
                visited[nx][ny][ndir][0] = nUsedT
            }
            if nUsedC < old[1] {
                visited[nx][ny][ndir][1] = nUsedC
            }
            q = append(q, State{nx, ny, ndir, nUsedT, nUsedC})
        }
    }
    return false
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    scanner.Scan()
    parts := strings.Split(scanner.Text(), " ")
    t, _ := strconv.Atoi(parts[0])
    c, _ := strconv.Atoi(parts[1])
​
    scanner.Scan()
    parts = strings.Split(scanner.Text(), " ")
    n, _ := strconv.Atoi(parts[0])
    m, _ := strconv.Atoi(parts[1])
​
    grid := make([][]byte, n)
    startX, startY := -1, -1
    for i := 0; i < n; i++ {
        scanner.Scan()
        line := scanner.Text()
        grid[i] = []byte(line)
        for j := 0; j < m; j++ {
            if grid[i][j] == 'S' {
                startX, startY = i, j
            }
        }
    }
​
    if bfs(grid, t, c, n, m, startX, startY) {
        fmt.Println("YES")
    } else {
        fmt.Println("NO")
    }
}
